import os
import sqlite3
import hashlib
import hmac
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/data/users.db'
SECRET_KEY = os.environ.get('HMAC_SECRET', 'default-dev-key')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        password_hash TEXT NOT NULL,
        email TEXT,
        role TEXT DEFAULT 'user',
        api_key TEXT,
        department TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        username TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()
    db.close()

def verify_request_signature(req):
    """Verify HMAC signature for API requests"""
    sig = req.headers.get('X-Request-Signature', '')
    body = req.get_data(as_text=True)
    expected = hmac.new(SECRET_KEY.encode(), body.encode(), hashlib.sha256).hexdigest()
    return hmac.compare_digest(sig, expected)

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by department and role filters"""
    department = request.args.get('department', '')
    role = request.args.get('role', '')
    sort_by = request.args.get('sort', 'username')

    # Basic input length check
    if len(department) > 100 or len(role) > 50:
        return jsonify({'error': 'Input too long'}), 400

    # Build query with filters
    base_query = "SELECT username, email, department, role FROM users WHERE 1=1"

    if department:
        base_query += f" AND department = '{department}'"
    if role:
        base_query += f" AND role = '{role}'"

    # Apply sorting - whitelist approach for sort column
    allowed_sorts = ['username', 'email', 'department', 'role']
    if sort_by not in allowed_sorts:
        sort_by = 'username'
    base_query += f" ORDER BY {sort_by}"

    try:
        db = get_db()
        results = db.execute(base_query).fetchall()
        users = [dict(row) for row in results]

        # Log the search action
        db.execute(
            "INSERT INTO audit_log (action, username) VALUES (?, ?)",
            (f"search:dept={department},role={role}", request.remote_addr)
        )
        db.commit()

        return jsonify({'users': users, 'count': len(users)})
    except Exception as e:
        return jsonify({'error': 'Query failed', 'detail': str(e)}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user by ID"""
    db = get_db()
    user = db.execute(
        "SELECT username, email, department, role FROM users WHERE id = ?",
        (user_id,)
    ).fetchone()
    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'Not found'}), 404

@app.route('/api/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.3.1'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
